using System.Linq;
public class C
{
    public static void Main()
    {
        var query =
            from a in new int[] { 1, 2, 2}
            where (a, 2) == (2, a)
            select a;

        foreach (var i in query)
        {
            System.Console.Write(i);
        }
    }
}
